/* Song and level registry for the FNF PS2 port.
 *
 * The data itself lives in song_registry_data.inc, which is GENERATED by
 * tools/gen_song_registry.py from the game's own JSON under assets-data/.
 * This file holds the API and the checks; the .inc holds the tables.
 *
 * Why generated: the first version of the tables was typed by hand and two
 * entries were wrong -- the Tutorial's opponent (it is the girlfriend, not
 * Dad) and week4's song order (satin-panties, high, milf). Both mistakes came
 * from reading funkin/InitState.hx and inferring, instead of reading the
 * shipped JSON. Now the C is a rendering of the JSON and cannot drift.
 */
#ifndef FNF_PS2_SONG_REGISTRY_H
#define FNF_PS2_SONG_REGISTRY_H

/* The original has two note sprites: the normal one and the chunky pixel one
 * used by week6. They are different atlases, so the scene layer has to know
 * which to load. */
typedef enum {
    SR_NOTE_FUNKIN = 0,
    SR_NOTE_PIXEL = 1
} sr_note_style_t;

/* playData.difficulties, as a bitmask. Every base-game song ships all three,
 * but the mask keeps a future song from silently missing one. */
#define SR_DIFF_EASY   0x01u
#define SR_DIFF_NORMAL 0x02u
#define SR_DIFF_HARD   0x04u
#define SR_DIFF_ALL    (SR_DIFF_EASY | SR_DIFF_NORMAL | SR_DIFF_HARD)

/* playData.songVariations. The Freeplay menu lists these; the port starts
 * with the default variation only, but the flags record what exists. */
#define SR_VAR_ERECT 0x01u
#define SR_VAR_PICO  0x02u
#define SR_VAR_BF    0x04u

/* One song. Mirrors funkin.data.song.SongData.playData plus the fields the
 * metadata JSON carries at its top level. */
typedef struct {
    const char *id;             /* "bopeebo" -- also the folder name */
    const char *display_name;   /* "Bopeebo" -- shown in Freeplay */
    const char *artist;
    const char *charter;

    const char *player;         /* character id, see bs_dados.h */
    const char *girlfriend;     /* NULL when the song has no girlfriend slot */
    const char *opponent;

    const char *stage;          /* stage id, see bs_dados.h */
    sr_note_style_t note_style;
    unsigned int difficulties;  /* SR_DIFF_* */
    unsigned int variations;    /* SR_VAR_* */
    float bpm;                  /* timeChanges[0].bpm, the chart's opening bpm */
} sr_song_t;

/* One story-mode week. Mirrors funkin.data.story.level.LevelData. */
typedef struct {
    const char *id;             /* "week1" */
    const char *display_name;   /* "DADDY DEAREST" -- shown on the title card */
    const char *title_asset;    /* "storymenu/titles/week1" */
    unsigned int background;    /* 0xRRGGBB; the level JSON stores "#F9CF51" */
    int has_capsule;            /* 0 unless the week shows a capsule label */
    const char *capsule_title;  /* e.g. "SP. COLLAB 1" for sserafim */

    const sr_song_t *const *songs;
    unsigned int song_count;
} sr_level_t;

/* Number of weeks, in story-menu order. */
#define SR_LEVEL_COUNT 10
/* Most songs in one week: weekend1 has four. */
#define SR_MAX_SONGS_PER_LEVEL 4

/* All weeks, in the order LevelRegistry.listBaseGameEntryIds() returns them:
 * tutorial, week1..week7, weekend1, sserafim. Never NULL. */
const sr_level_t *const *sr_levels(void);

/* Number of weeks, in story-menu order. Same as SR_LEVEL_COUNT, but a
 * function so callers do not have to trust the macro. */
unsigned int sr_level_count(void);

/* Total number of songs across all weeks. */
unsigned int sr_song_count(void);

/* Week by index (0..SR_LEVEL_COUNT-1), or NULL when out of range. */
const sr_level_t *sr_level(unsigned int index);

/* Week by id ("week1"), or NULL when there is no such week. */
const sr_level_t *sr_level_by_id(const char *id);

/* Song by id, searching every week, or NULL. */
const sr_song_t *sr_song_by_id(const char *id);

/* True when the difficulty is present for this song. */
int sr_song_has_difficulty(const sr_song_t *s, unsigned int diff);

/* Append "<root>/songs/<id>/<difficulty>.chart" to out.
 * difficulty is "easy", "normal" or "hard".
 * Returns the length written, or the length that would have been written
 * (excluding the NUL) when out is too small -- so a caller can size a buffer
 * by calling once with NULL. Returns -1 on a bad argument. */
int sr_chart_path(char *out, unsigned int out_size, const char *root,
                  const sr_song_t *s, const char *difficulty);

/* How many pendrive layouts sr_chart_path_at() knows about. */
int sr_chart_layout_count(void);

/* The chart path for one specific layout. Layout 0 is the original game's tree
 * (songs/<id>/<difficulty>.chart); the others are flat fallbacks for pendrives
 * whose PS2 USB storage driver will not open a nested tree. Returns the length
 * written, or -1 on a bad argument or an unknown layout. */
int sr_chart_path_at(char *out, unsigned int out_size, const char *root,
                     const sr_song_t *s, const char *difficulty,
                     unsigned int layout);

/*
 * Append "<root>/songs/<id>/stems.pcm": o arquivo de audio do port.
 *
 * Por que nao o Inst.pcm do original: no jogo original o instrumental e as
 * vozes sao DUAS faixas PCM tocadas juntas (songs/<id>/Inst.ogg e
 * Voices-<char>.ogg), e o volume de cada uma muda durante a musica. O port
 * ainda tem um unico fluxo de audio, com instrumental e vozes ja' misturados
 * por quadro, no formato de 8 bytes por amostra (inst L,R + vozes L,R) --
 * que e' o que audio_stems.pcm sempre foi. Usar Inst.pcm aqui seria pior:
 * o mixer leria 8 bytes por amostra de um arquivo de 4 e tocaria na metade
 * da velocidade, com o canal errado.
 *
 * Quando o mixer passar a tocar duas faixas (item aberto na Fase 2), este
 * caminho some e o port passa a usar sr_instrumental_path() e
 * sr_vocals_path() sem conversao.
 */
int sr_stems_path(char *out, unsigned int out_size, const char *root,
                  const sr_song_t *s);

/* Append "<root>/songs/<id>/Inst.pcm". */
int sr_instrumental_path(char *out, unsigned int out_size, const char *root,
                         const sr_song_t *s);

/* Append "<root>/songs/<id>/Voices-<bf|dad>.pcm".
 * side is "bf" for the player's vocals or "dad" for the opponent's. */
int sr_vocals_path(char *out, unsigned int out_size, const char *root,
                   const sr_song_t *s, const char *side);

/* Append "<root>/chars/<character>.pack". */
int sr_character_path(char *out, unsigned int out_size, const char *root,
                      const char *character);

/* Check every character and stage id against the official tables in
 * bs_dados.h. `report` receives one line per problem (plus a summary line);
 * pass NULL for a silent check. Returns the number of problems found.
 *
 * A song whose metadata has not been collected yet reports its player and
 * opponent as PENDENTE rather than as an error: that is a known gap, not a
 * wrong id. The test suite asserts the pending count separately, so a genuine
 * typo still fails. */
int sr_validate(void (*report)(const char *fmt, ...));

#endif /* FNF_PS2_SONG_REGISTRY_H */
